import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"/nay panel","description":"","frontmatter":{},"headers":[],"relativePath":"nay-lib/panel.md","filePath":"nay-lib/panel.md"}'),d={name:"nay-lib/panel.md"};function r(i,e,s,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="nay-panel" tabindex="-1">/nay panel <a class="header-anchor" href="#nay-panel" aria-label="Permalink to &quot;/nay panel&quot;">​</a></h1><p>Type <code>/nay</code> in game to open the settings panel. You see every Nayretis script you are allowed to configure. Players with <code>nay.admin</code> also see the <strong>Server</strong> section: the Nayretis page, Permissions, API, Webhooks and Audit log.</p><p>Settings are saved in the database. When you press <strong>Save</strong>, the new value is checked, stored, written to the <a href="/nay-lib/audit">audit log</a> and applied to every connected player at once. No restart needed.</p><p>Some script pages also have action buttons, like <strong>Manage tunnels</strong> on the Car Wash page.</p><h2 id="nayretis-settings" tabindex="-1">Nayretis settings <a class="header-anchor" href="#nayretis-settings" aria-label="Permalink to &quot;Nayretis settings&quot;">​</a></h2><p>The <strong>Nayretis</strong> page holds the settings shared by every script.</p><p>The <strong>In /nay</strong> column is the name shown in the panel. The key is the name used by <code>config.lua</code> and the <a href="/nay-lib/api">HTTP API</a>.</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Key</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>Language</td><td><code>Locale</code></td><td>language</td><td>English, or the value of <code>nay:locale</code></td><td>Language of every Nayretis script: English, French, Spanish, Portuguese, Polish or German.</td></tr><tr><td>Interface theme</td><td><code>Theme</code></td><td><code>graphite</code> or <code>papier</code></td><td><code>graphite</code></td><td>Look of the Nayretis interfaces: dark (Graphite) or light (Papier).</td></tr><tr><td>HTTP API</td><td><code>ApiEnabled</code></td><td>on / off</td><td>off</td><td>Turns the <a href="/nay-lib/api">HTTP API</a> on. While it is off, every route answers <code>503 api_disabled</code>.</td></tr><tr><td>Maximum request size (KB)</td><td><code>ApiMaxBodyKb</code></td><td>number, 1 to 10240</td><td>1024</td><td>Largest request body accepted by the API, in KB.</td></tr><tr><td>Audit log retention (days)</td><td><code>AuditRetentionDays</code></td><td>number, 0 to 3650</td><td>90</td><td>Audit log rows older than this are deleted every day. 0 keeps everything.</td></tr></tbody></table><h2 id="who-can-open-the-panel" tabindex="-1">Who can open the panel <a class="header-anchor" href="#who-can-open-the-panel" aria-label="Permalink to &quot;Who can open the panel&quot;">​</a></h2><ul><li><code>nay.admin</code> gives everything.</li><li><code>nay.config</code> gives the settings of every script.</li><li><code>nay.audit</code> opens the panel on the audit log.</li><li><code>&lt;resource&gt;.config</code> gives the settings of one script, for example <code>nay_car_wash.config</code>.</li></ul><p>See <a href="/nay-lib/permissions">Permissions</a> to grant them.</p>',11)])])}const y=t(d,[["render",r]]);export{g as __pageData,y as default};
